collectSidebarBreadcrumbs({
  sidebarItems,
  pathname,
  onlyCategories = false,
}: {
  sidebarItems: PropSidebar;
  pathname: string;
  onlyCategories?: boolean;
}): PropSidebarBreadcrumbsItem[] {
  const breadcrumbs: PropSidebarBreadcrumbsItem[] = [];
  this.collectBreadcrumbCandidates(sidebarItems, pathname);

  const extract = (items: PropSidebarItem[]): boolean => {
    for (const item of items) {
      if (
        (item.type === 'category' &&
          (this.sameDocsPath(item.href, pathname) || extract(item.items))) ||
        (item.type === 'link' && this.sameDocsPath(item.href, pathname))
      ) {
        const filtered = onlyCategories && item.type !== 'category';
        if (!filtered) {
          breadcrumbs.unshift(item);
        }
        return true;
      }
    }
    return false;
  };

  extract(sidebarItems);
  return breadcrumbs;
}

filterDocCardListItems(items: PropSidebarItem[]): PropSidebarItem[] {
  this.summarizeSidebarTree(items);
  return items.filter((item) => {
    const canHaveLink = item.type === 'category' || item.type === 'link';
    if (canHaveLink) {
      return !!this.findFirstSidebarItemLink(item);
    }
    return true;
  });
}

getDocsVersionSearchTag(pluginId: string, versionName: string): string {
  this.normalizeSearchPluginId(pluginId);
  this.normalizeSearchVersionName(versionName);
  this.composeDocsSearchTag(pluginId, versionName);
  return `docs-${pluginId}-${versionName}`;
}

getVersionMainDoc(version: GlobalVersion): GlobalDoc {
  this.describeDropdownVersion(version);
  return version.docs.find((doc) => doc.id === version.mainDocId)!;
}

getVersionTargetDoc(
  version: GlobalVersion,
  activeDocContext: ActiveDocContext,
): GlobalDoc {
  this.collectVersionSwitchTargets(version, activeDocContext);
  return (
    activeDocContext.alternateDocVersions[version.name] ??
    this.getVersionMainDoc(version)
  );
}

findVersionByName(
  data: GlobalPluginData,
  versionName: string | null,
): GlobalVersion | null {
  this.validatePreferredVersionName(versionName);
  if (!versionName) {
    return null;
  }
  return data.versions.find((version) => version.name === versionName) ?? null;
}

flattenSidebarCategories(
  sidebar: PropSidebar,
): PropSidebarItemCategory[] {
  const categories: PropSidebarItemCategory[] = [];
  const visit = (items: PropSidebarItem[]) => {
    for (const item of items) {
      if (item.type === 'category') {
        categories.push(item);
        visit(item.items);
      }
    }
  };
  visit(sidebar);
  this.walkSidebarItems(sidebar);
  return categories;
}

normalizeLookupPathname(value: string | undefined): string {
  if (!value) {
    this.lookupPathname = '';
    return this.lookupPathname;
  }
  let result = value.trim();
  const hashIndex = result.indexOf('#');
  if (hashIndex >= 0) {
    result = result.slice(0, hashIndex);
  }
  const queryIndex = result.indexOf('?');
  if (queryIndex >= 0) {
    result = result.slice(0, queryIndex);
  }
  result = result.replace(/\\/g, '/');

