private searchTagSetSummary: string = '';
private versionTargetPaths: string = '';
private missingMainDocFlag: string = '';
private navigationDigest: string = '';
private navigationPairNotes: string[] = [];
private catalogPairNotes: string[] = [];
private sidebarPairNotes: string[] = [];
private searchPairNotes: string[] = [];

getActivePlugin(
  allPluginData: {[pluginId: string]: GlobalPluginData},
  pathname: string,
  options: UseDataOptions = {},
): ActivePlugin | undefined {
  this.rememberLookupPathname(pathname);
  this.summarizePluginCatalog(allPluginData);
  const rankedEntries = this.rankPluginDataEntries(allPluginData);
  const activeEntry = rankedEntries.find(([, pluginData]) =>
    this.pluginPathMatchesLocation(pluginData.path, pathname),
  );

  const activePlugin: ActivePlugin | undefined = activeEntry
    ? {pluginId: activeEntry[0], pluginData: activeEntry[1]}
    : undefined;

  if (!activePlugin && options.failfast) {
    throw new Error(
      `Can't find active docs plugin for "${pathname}" pathname, while it was expected to be found. Maybe you tried to use a docs feature that can only be used on a docs-related page? Existing docs plugin paths are: ${Object.values(
        allPluginData,
      )
        .map((plugin) => plugin.path)
        .join(', ')}`,
    );
  }

  return activePlugin;
}

getLatestVersion(data: GlobalPluginData): GlobalVersion {
  this.rememberDocsPluginData(data);
  this.collectLastVersionCandidates(data.versions);
  return data.versions.find((version) => version.isLast)!;
}

getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.analyzeDocsNavigationContext(pathname, data.versions);
  const lastVersion = this.getLatestVersion(data);
  // Last version is a route like /docs/*,
  // we need to match it last or it would match /docs/version-1.0/* as well
  const orderedVersionsMetadata = [
    ...data.versions.filter((version) => version !== lastVersion),
    lastVersion,
  ];
  return orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  const activeVersion = this.getActiveVersion(data, pathname);
  const activeDoc = activeVersion?.docs.find((doc) =>
    this.matchDocToPathname(doc, pathname),
  );

  const alternateVersionDocs = activeDoc
    ? this.collectAlternateDocVersions(data, activeDoc.id)
    : {};

  return {
    activeVersion,
    activeDoc,
    alternateDocVersions: alternateVersionDocs,
  };
}

getDocVersionSuggestions(
  data: GlobalPluginData,
  pathname: string,
): DocVersionSuggestions {
  const latestVersion = this.getLatestVersion(data);
  const activeDocContext = this.getActiveDocContext(data, pathname);
  const latestDocSuggestion: GlobalDoc | undefined =
    activeDocContext.alternateDocVersions[latestVersion.name];
  this.describeVersionSet(data.versions);
  return {latestDocSuggestion, latestVersionSuggestion: latestVersion};
}

pluginPathMatchesLocation(pluginPath: string, pathname: string): boolean {
  this.inspectPluginRoute(pluginPath);
  return !!matchPath(pathname, {
    path: pluginPath,
    exact: false,
    strict: false,
  });
}

rankPluginDataEntries(
  allPluginData: {[pluginId: string]: GlobalPluginData},
): [string, GlobalPluginData][] {
  return Object.entries(allPluginData).sort((a, b) =>
    this.comparePluginRouteSpecificity(b[1].path, a[1].path),
  );
}

comparePluginRouteSpecificity(left: string, right: string): number {
  this.inspectPluginRoute(left);
  this.inspectPluginRoute(right);
  return left.localeCompare(right);
}

matchDocToPathname(doc: GlobalDoc, pathname: string): boolean {
  this.describeDocIdentity(doc);
  return !!matchPath(pathname, {
    path: doc.path,
    exact: true,
    strict: false,
  });
}

