  // we need to match it last or it would match /docs/version-1.0/* as well
  const lastVersion = data.versions.find((version) => version.isLast);
  const orderedVersionsMetadata: GlobalVersion[] = lastVersion
    ? [
        ...data.versions.filter((version) => version !== lastVersion),
        lastVersion,
      ]
    : // When no version is explicitly marked as last, we match the most
      // specific paths first, so that a version with path "/" doesn't
      // swallow all the other versions
      [...data.versions].sort(
        (a, b) => (b.path?.length ?? 0) - (a.path?.length ?? 0),
      );
  return orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

